import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Relazione d'ordine","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/j_teoria-degli-insiemi/jc/jch.md","filePath":"lezioni/j_teoria-degli-insiemi/jc/jch.md"}`),a={name:`lezioni/j_teoria-degli-insiemi/jc/jch.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="relazione-d-ordine" tabindex="-1">Relazione d&#39;ordine <a class="header-anchor" href="#relazione-d-ordine" aria-label="Permalink to “Relazione d&#39;ordine”">​</a></h1><p>Diciamo che la relazione <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>R</mi></mrow><annotation encoding="application/x-tex">R</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span> su <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi><mo>×</mo><mi>A</mi></mrow><annotation encoding="application/x-tex">A \\times A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">A</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span></span></span></span> è <strong>d&#39;ordine</strong> se è contemporaneamente riflessiva, antisimmetrica e transitiva.</p><blockquote><p class="text-blue"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mi>R</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{R}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;color:red;">R</span></span></span></span> è relazione d&#39;ordine se è [riflessiva]{.text-blue} [antisimmetrica]{.text-blue} [transitiva]</p></blockquote><blockquote><p>In pratica avrai una relazione d&#39;ordine se puoi dire se tra due elementi uno è minore o uguale (oppure maggiore o uguale) all&#39;altro.</p></blockquote><p>Se su un insieme è possibile individuare una relazione d&#39;ordine allora è possibile ordinare l&#39;insieme stesso e l&#39;insieme viene detto <strong>ordinato</strong>. Due suoi elementi cui si applica la relazione sono <strong>confrontabili</strong> nel senso che si può dire se il primo precede (o segue) il secondo.</p><p>Approfondiamo un po&#39; il concetto di relazione d&#39;ordine:</p><ul><li><a href="./jcha.html">Relazione d&#39;ordine stretto</a></li><li><a href="./jchb.html">Relazione d&#39;ordine totale <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi mathvariant="double-struck">N</mi></mrow><annotation encoding="application/x-tex">\\mathbb{N}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6889em;"></span><span class="mord mathbb">N</span></span></span></span></a></li><li><a href="./jchc.html">Relazione lineare <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi mathvariant="double-struck">N</mi></mrow><annotation encoding="application/x-tex">\\mathbb{N}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6889em;"></span><span class="mord mathbb">N</span></span></span></span></a></li></ul><p>Vediamone alcuni esempi:</p><blockquote><p>Per le proprietà riflessiva, simmetrica, antisimmetrica e transitiva degli esempi fai riferimento agli esempi corrispondenti delle pagine precedenti.</p></blockquote><p>Considero l&#39;insieme degli abitanti dell&#39;Italia e considero la relazione [<strong>&quot;abita nella stessa città&quot;</strong>]{.text-red}. La relazione non è di ordine: infatti è riflessiva e transitiva ma non antisimmetrica.</p><hr><p>Considero i numeri naturali e considero la relazione [<strong>&quot;è maggiore o uguale a&quot;</strong>]{.text-red}. La relazione è d&#39;ordine infatti: è riflessiva, antisimmetrica e transitiva e i numeri si possono ordinare ad esempio in ordine crescente:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="red"><mn>1</mn><mo separator="true">,</mo><mn>2</mn><mo separator="true">,</mo><mn>3</mn><mo separator="true">,</mo><mn>4</mn><mo separator="true">,</mo><mn>5</mn><mo separator="true">,</mo><mn>6</mn><mo separator="true">,</mo><mo>…</mo></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{1, 2, 3, 4, 5, 6, \\dots} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord" style="color:red;">1</span><span class="mpunct" style="color:red;">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord" style="color:red;">2</span><span class="mpunct" style="color:red;">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord" style="color:red;">3</span><span class="mpunct" style="color:red;">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord" style="color:red;">4</span><span class="mpunct" style="color:red;">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord" style="color:red;">5</span><span class="mpunct" style="color:red;">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord" style="color:red;">6</span><span class="mpunct" style="color:red;">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner" style="color:red;">…</span></span></span></span></span></p><hr><p>Supponiamo di avere un caseggiato di più piani che abbia una famiglia per ogni piano e considero la relazione [<strong>&quot;la famiglia <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi></mrow><annotation encoding="application/x-tex">X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span> abita allo stesso piano oppure ad un piano superiore della famiglia <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Y</mi></mrow><annotation encoding="application/x-tex">Y</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">Y</span></span></span></span>&quot;</strong>]{.text-red}. La relazione è d&#39;ordine: infatti è riflessiva, antisimmetrica e transitiva; possiamo ordinare gli elementi come:</p><ul><li>[famiglia del pianterreno]{.text-</li></ul>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};